        | project TimeGenerated, Telemetry='MDE/Endpoint', Operation=tostring(ActionType), EventGroup=grp,
                  Actor=user, Device=tostring(DeviceName), SourcePath=iff(isnotempty(oldPath), oldPath, currentPath),
